'use strict';

/**
 * NodeJs-Unreal bundled drop-in for the `ipc-event-emitter` npm package.
 *
 * Wire-compatible: messages over a real IPC channel use the same envelope the
 * original package uses, `{ type: 'ipc-event-emitter', emit: [name, ...args] }`,
 * so the genuine npm package and this one interoperate.
 *
 * Two transports, chosen automatically from the passed process object:
 *   - Forked subprocess: a real IPC channel exists (`process.send` + channel),
 *     so we behave exactly like classic ipc-event-emitter. process.js bridges
 *     these messages to/from Unreal.
 *   - Inline script (run via require inside process.js): no IPC channel, so we
 *     bind to the Unreal bridge installed on globalThis by process.js.
 *
 * Usage in a script (identical to the npm package):
 *   const ipc = require('ipc-event-emitter').default(process);
 *   ipc.on('myevent', (vars) => ipc.emit('result', compute(vars)));
 */

const EventEmitter = require('events');

const TYPE = 'ipc-event-emitter';

class IPCEventEmitter extends EventEmitter {
	constructor($process) {
		super();
		this._process = $process;

		// A forked child has a live IPC channel; an inline script does not.
		this._hasChannel = !!(
			$process &&
			typeof $process.send === 'function' &&
			typeof $process.on === 'function' &&
			$process.channel
		);

		if (this._hasChannel) {
			$process.on('message', (data) => {
				if (data && data.type === TYPE && Array.isArray(data.emit)) {
					super.emit.apply(this, data.emit);
				}
			});
		} else {
			// Inline path: bind to the Unreal bridge that process.js installs.
			this._bridge = globalThis.__unrealBridge || null;
			this._scriptName = globalThis.__currentInlineScript || '';
			if (this._bridge) {
				this._bridge.registerInline(this._scriptName, this);
			}
		}
	}

	/** Called by process.js to deliver an incoming Unreal->script event (inline path). */
	_deliver(name, args) {
		super.emit.apply(this, [name, ...args]);
	}

	emit(...args) {
		const name = args[0];

		// Never ship EventEmitter's internal bookkeeping events across the wire.
		if (name === 'newListener' || name === 'removeListener') {
			return super.emit.apply(this, args);
		}

		if (this._hasChannel) {
			try {
				this._process.send({ type: TYPE, emit: args });
			} catch (e) {
				// channel closed mid-flight; ignore
			}
		} else if (this._bridge) {
			this._bridge.sendEvent(this._scriptName, name, args.slice(1));
		}
		return this;
	}

	// Compatibility surface. The original package supports pinning (sticky events
	// for late listeners); for the Unreal bridge a plain emit is sufficient.
	pin(...args) {
		return this.emit(...args);
	}
	unpin() {
		return this;
	}
	fix() {
		return this;
	}
}

function IPC($process) {
	return new IPCEventEmitter($process);
}

module.exports = IPC;
module.exports.default = IPC;
module.exports.IPC = IPC;
module.exports.IPCEventEmitter = IPCEventEmitter;
